     // Extract parameters
      double mean  = gaus.GetParameter(1);
      double sigma = gaus.GetParameter(2);
      //~ cout << " FITEO " << endl;
      //~ std::cout << "Bin " << iBin 
                //~ << ": mean=" << mean << ", sigma=" << sigma 
                //~ << ", sigma%=" << (sigma*100.0/mean) << std::endl;

