vector<Double_t> Seed; /*vector de flujo semilla*/
vector<Double_t> dE; /*Vector de anchos de energia*/
vector<Double_t> B; /*bins*/ /*matriz de bordes de bins*/
vector<Double_t> E; /*bins*/ /*matriz de Energias*/


