	/*Calculamos los flujos EM_MC_stop de acuerdo a su representacion*/
	vector<double> flux_median;
	vector<double> flux_error_lower;
	vector<double> flux_error_upper;
	
	//~ for (int i = 0; i < deconv_median_vec.size()-1; i++) //reducimos el tamanio de los vectores de flujo a 129, para tener un vector de bordes de bin de 130 de tamanio
	for (int i = 0; i < deconv_median_vec.size(); i++) // deconv_median_vec ya es de 129 (0-128):129
		{
			double E_mid;
			double E_wid;
			
			if(flux_representation=="Integral")
				{
					E_mid = 1.0; // integral flux
					E_wid = 1.0;
				}
			if(flux_representation=="Lethargy")
				{
					E_mid = emid_icrp116_vec[i]; // per unit lethargic
					E_wid = ewid_icrp116_vec[i];
				}
			if(flux_representation=="Differential")
				{
					E_mid = 1.0; //differential flux
					E_wid = ewid_icrp116_vec[i];
				}
			//~ if(cout << " <----- Bad representation name ----> " << endl;  return; )

			// deconv_median_vec es un flujo integral
			flux_median.push_back(deconv_median_vec[i]*(E_mid/E_wid));
			flux_error_lower.push_back(deconv_error_lower_vec[i]*(E_mid/E_wid));
			flux_error_upper.push_back(deconv_error_upper_vec[i]*(E_mid/E_wid));
		}

	cout << "flux_median size=" << flux_median.size()  << endl; //129
	
	/*medianas de flujo del EM_MC_stop como array*/
	double *emid_array = emid_icrp116_vec.data(); // x array
	//~ double *median_flux_array = deconv_median_vec.data(); // y array
	double *median_flux_array = flux_median.data(); // y array
