//~ string roundedTime_init = roundToNearestMinute(utc_init_vec_0_value);
string roundedTime_init_forward = roundToNearestMinute(utc_init_vec_forward_0_value);
string roundedTime_FTE = roundToNearestMinute(Starting_time_FTE_utc_0_value);
string roundedTime_last = roundToNearestMinute(lmt_dlt_utc_vec_0_value);
