//~ cout << "Rounded init time in UTC of Campaign: " << roundedTime_init << endl;
cout << "Rounded init forward time in UTC of Campaign: " << roundedTime_init_forward << endl;
cout << "Rounded FTE time in UTC of Campaign: " << roundedTime_FTE << endl;
cout << "Rounded last time in UTC of Campaign: " << roundedTime_last << endl;

/******************/;

//~ size_t pos_t = utc_init_vec_0_value.find_first_of("T");
