    gr_2->Fit(f_2,"MLE");   // usa ey → w_i = 1 / ey[i]^2 = 1 / Mt[i]^2

    gr_2->Draw("AP");
    f_2->Draw("same");

    // ------------------------------------------------------------
    // 5) Extraer parámetros e imprimirlos
    // ------------------------------------------------------------
    double k_2  = f_2->GetParameter(0);
    //~ double a_2  = f_2->GetParameter(1);
    double S_2  = f_2->GetParameter(1);

