    double mean  = res.mean_dispersion_crps;   // median / 60
	double sigma = res.sigma_dispersion_crps;  // sigma_eq / 60
	
	double mean_timegrid_meas  = res.median ;   // median timegrid
	double sigma_timegrid_meas = res.sigma_eq;  // sigma_eq  timegrid
	
	
	TH1D* hist_proj = res.hproj;  // hist projection
	
	/*Correcion de tiempo muerto*/
	 double tau = 2.4E-05; // s ((1/(62.5 MHz))*1500 = 24 us)
	
	 double tau_timegrid_meas;
	 
	 if(timegrid==0){tau_timegrid_meas = 2.4E-05;} //  1s
	 else if(timegrid==1){tau_timegrid_meas = 4.0E-07;} //  1min
	 else if(timegrid==2){tau_timegrid_meas =  2.6E-08;} //  15min
	
	 double mean_corr = mean/(1.0-mean*tau); /**Correccion de tiempo muerto**/
	/*Sigma n corrected*/
	double sigma_corrected = sigma/pow((1.0-mean*tau),2.);

	/*************************/
